class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print(f'{self.name} makes a sound.')

a = Animal('Generic')
a.speak()

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print(f'{self.name} makes a sound.')

class Cat(Animal):
    def speak(self):
        print(f'{self.name} says: Meow!')

cat = Cat('Whiskers')
cat.speak()

class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print(f'{self.name} makes a sound.')

class Dog(Animal):
    def __init__(self, name):
        super().__init__(name)

    def speak(self):
        print(f'{self.name} says: Woof!')

    def fetch(self):
        print(f'{self.name} fetches the ball!')

dog = Dog('Rex')
dog.speak()
dog.fetch()

class Shape:
    def area(self):
        return 0

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14159 * self.radius ** 2

class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side ** 2

print(Shape().area())
print(Circle(2).area())
print(Square(3).area())

class Animal:
    def __init__(self, name):
        self.name = name

class Dog(Animal):
    pass

dog = Dog('Rex')
print(isinstance(dog, Dog))
print(isinstance(dog, Animal))
print(isinstance(dog, str))

class Vehicle:
    def __init__(self, speed, fuel):
        self.speed = speed
        self.fuel = fuel

class Car(Vehicle):
    def __init__(self, speed, fuel, doors):
        super().__init__(speed, fuel)
        self.doors = doors

class Truck(Vehicle):
    def __init__(self, speed, fuel, cargo_capacity):
        super().__init__(speed, fuel)
        self.cargo_capacity = cargo_capacity

car = Car(120, 'petrol', 4)
truck = Truck(90, 'diesel', 5000)
print(car.speed, car.fuel, car.doors)
print(truck.speed, truck.fuel, truck.cargo_capacity)

